            400: components["responses"]["ValidationError"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["CSRFError"];
            404: components["responses"]["NotFound"];
            /** @description State version or transition conflict. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
